mapper.select:
select * from REP_PROD_INDEX
where VALUE_DATE     >=  #{beforeDate,jdbcType=TIMESTAMP}
and VALUE_DATE     <=   #{endDate,jdbcType=TIMESTAMP} 
and PROD_ID=#{prodId,jdbcType=VARCHAR}

select * from FIN_PRODUCT 
WHERE FINPROD_ID=#{prodId}
AND FINPROD_TYPE='F16'

 select * from MST_HOLIDAY
	where CDATE  >=   #{startDate} 
	and CDATE   <=   #{endDate} 
	and CALENDAR_ID=#{calendarId}

select  
  to_char(VALUE_DATE,'yyyy-MM') yDate,
  sum(W_YIELD) swYield
  from  REP_PROD_INDEX
  where  
  VALUE_DATE     >=  #{beforeDate,jdbcType=TIMESTAMP}
  and VALUE_DATE     <=   #{endDate,jdbcType=TIMESTAMP} 
  and PROD_ID=#{prodId,jdbcType=VARCHAR}
  group by to_char(VALUE_DATE,'yyyy-MM')
